export const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
export function seededRandom(seed=1){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296;};}
export function createTeams(seed){return createScienceMatch(seed).teams;}
export function createExpedition(seed=Date.now()%999999){const match=createScienceMatch(seed);return {match,credits:4800,upgrades:[],cargoCapacity:6,extraLoad:0,eva:false,scanBoost:0,overdrive:0,flightLeg:'outbound',seed,mode:'menu',phase:'assembly',selected:3,views:['third','third','third','third'],parts:PARTS.map(p=>({...p,position:shipPoint(p.position),size:shipSize(p.size),stage:'shelf',price:[220,180,300,400,280,240,200,260,120,360,300,200][PARTS.indexOf(p)],purchased:false,bolts:[0,0,0],aiTime:0})),autoBuild:{enabled:false,t:0,priority:'standard'},constructionStyle:'guided',crewActions:{humanModules:0,combatHits:0,samples:0},carry:[null,null,null,null],rotation:[0,0,0,0],cargo:CARGO.map((c,i)=>({...c,position:[CARGO_SPOTS[i][0],-.135,CARGO_SPOTS[i][1]],stowed:false})),checks:{pressure:0,power:0,engine:0},checkReadings:{pressure:0,power:45,engine:0},teams:match.teams,elapsed:0,flightTime:0,route:null,hull:100,power:3.6,powerCapacity:6,reactor:62,temperature:41,pressure:101.3,co2:480,food:8,water:16,crewNutrition:100,spares:6,oxygenPacks:3,propellant:80,wetMass:750,oxygenSuit:100,panels:[{id:'port',name:'Port coolant plate',offset:shipOffset([-3.5,1.37,.8]),health:100,removed:false,progress:0},{id:'aft',name:'Aft shield plate',offset:shipOffset([1.05,.87,1.7]),health:100,removed:false,progress:0},{id:'starboard',name:'Starboard power cover',offset:shipOffset([3.5,1.37,.8]),health:100,removed:false,progress:0}],fault:null,faultClock:17,abilityCD:[0,0,0,0],altCD:[0,0,0,0],ultimate:[45,45,45,45],shield:0,boost:0,decoy:0,score:0,kills:0,science:0,won:false,ended:false,aiAssist:true,log:[],routeFuel:0,sensitivity:1,paused:false};}
export function assignPart(s,id,owner){if(s.mode!=='menu'&&s.mode!=='select')return false;const p=s.parts.find(p=>p.id===id);if(!p||!Number.isInteger(owner)||owner<0||owner>3)return false;p.owner=owner;return true;}
export function pickPart(s,id,role){if(s.autoBuild?.enabled)return false;const p=s.parts.find(p=>p.id===id);if(s.phase!=='assembly'||!p||p.owner!==role||p.stage!=='shelf'||s.carry[role])return false;if(!p.purchased){if(s.credits<p.price)return false;s.credits-=p.price;p.purchased=true;}p.stage='carried';s.carry[role]=id;s.rotation[role]=0;return true;}
export function rotateCarried(s,role){if(!s.carry[role])return false;s.rotation[role]=(s.rotation[role]+1)%4;return true;}
export function placePart(s,role,distance){if(s.autoBuild?.enabled)return false;const p=s.parts.find(p=>p.id===s.carry[role]);if(!p||p.stage!=='carried'||distance>3||s.rotation[role]!==p.angle)return false;p.stage='positioned';s.carry[role]=null;return true;}
export function fastenBolt(s,id,bolt,role,dt,distance,aligned=true,source='human'){if(s.autoBuild?.enabled)return false;const p=s.parts.find(p=>p.id===id);if(!p||p.owner!==role||p.stage!=='positioned'||distance>3.5||!aligned||!Number.isInteger(bolt)||bolt<0||bolt>2)return false;p.bolts[bolt]=clamp(p.bolts[bolt]+Math.max(0,dt)/.7,0,1);if(p.bolts[bolt]>1-1e-9)p.bolts[bolt]=1;if(p.bolts.every(b=>b>=1)){p.stage='secured';s.score+=75;if(source==='human'&&role===s.selected)recordCrewAction(s,'humanModules');if(s.parts.every(p=>p.stage==='secured'))s.phase='outfit';}return true;}
export function pickCargo(s,id,role){const c=s.cargo.find(c=>c.id===id);if(s.phase!=='outfit'||!c||c.stowed||s.carry[role]||s.carry.includes('cargo:'+id))return false;s.carry[role]='cargo:'+id;return true;}
export function stowCargo(s,role,distance){const id=s.carry[role];if(!id?.startsWith('cargo:')||distance>3)return false;const c=s.cargo.find(c=>c.id===id.slice(6));if(!c||c.stowed)return false;c.stowed=true;s.carry[role]=null;s.score+=60;return true;}
export function runCheck(s,type,role,dt,reading){if(s.phase!=='outfit'||!Object.hasOwn(s.checks,type)||!s.cargo.every(c=>c.stowed))return false;const required={pressure:1,power:1,engine:0};if(role!==required[type])return false;const range={pressure:[95,105],power:[45,65],engine:[68,78]}[type];s.checkReadings[type]=reading;if(reading<range[0]||reading>range[1])return false;s.checks[type]=clamp(s.checks[type]+dt/2.2,0,1);if(s.checks[type]>1-1e-9)s.checks[type]=1;if(Object.values(s.checks).every(v=>v>=1)){s.phase='route';s.score+=150;}return true;}
export function routeBudget(s,route){const r=typeof route==='string'?ROUTES.find(r=>r.id===route):route;if(!r)return null;const exhaust=360*9.80665,outbound=s.wetMass*(1-Math.exp(-r.dv/exhaust)),returnReserve=(s.wetMass-outbound)*(1-Math.exp(-95/exhaust)),contingency=5,slowClimb=slowClimbKg(designSheet(s).twr),required=outbound+returnReserve+contingency+slowClimb;return {...r,outbound,returnReserve,contingency,slowClimb,required,margin:s.propellant-required,valid:s.propellant>=required,exhaust};}
export function launchFlight(s,id){const r=routeBudget(s,id);if(s.phase!=='route'||!r?.valid)return false;s.route=r;s.routeFuel=r.outbound;s.propellant-=r.outbound+r.slowClimb;s.mode='play';s.phase='flight';s.flightTime=0;return true;}
export function tickSystems(s,dt,teamId=0,position=[0,2,0],planet='space'){if(s.phase!=='flight'||s.paused||s.ended)return;const t=clamp(dt,0,.1),load=5.4+s.extraLoad+(s.boost>0?2:0)+(s.fault==='power'?1.8:0),generation=s.reactor/100*9*(s.fault==='reactor'?.45:1);s.power=clamp(s.power+(generation-load)*t*30/3600,0,s.powerCapacity);s.temperature=clamp(s.temperature+(s.reactor/100*.25-.08+(s.fault==='cooling'?.45:0))*t,15,110);const leaking=s.panels.some(p=>p.health<60);s.pressure=clamp(s.pressure-(leaking?.42:0)*t,0,105);s.co2=clamp(s.co2+(s.fault==='scrubber'?22:1.5)*t,300,8000);s.crewNutrition=clamp(s.crewNutrition-t*.16,0,100);if(s.power<=.02||s.temperature>90||s.pressure<55||s.co2>5000)s.hull=Math.max(0,s.hull-t*1.3);for(let i=0;i<4;i++){s.abilityCD[i]=Math.max(0,s.abilityCD[i]-t);s.altCD[i]=Math.max(0,s.altCD[i]-t);s.ultimate[i]=Math.min(100,s.ultimate[i]+t*.8);}for(const k of ['shield','boost','decoy','scanBoost','overdrive'])s[k]=Math.max(0,s[k]-t);const pk=s.peak??={co2:0,temperature:0,minPower:Infinity};pk.co2=Math.max(pk.co2,s.co2);pk.temperature=Math.max(pk.temperature,s.temperature);pk.minPower=Math.min(pk.minPower,s.power);s.flightTime+=t;s.faultClock-=t;if(s.faultClock<=0){const rand=seededRandom(s.seed+Math.floor(s.flightTime)*67);s.fault=pickFault(designSheet(s),rand);const p=s.panels[Math.floor(rand()*s.panels.length)];p.health=Math.max(10,p.health-45);p.removed=false;p.progress=0;s.faultClock=faultInterval(s);s.log.push({time:s.flightTime,event:s.fault});}if(s.hull<=0){eliminateCrew(s.match,teamId,position,planet);s.phase='spectator';}}
export function maintainSystem(s,role,dt,system){if(s.phase!=='flight'||role!==1)return false;if(system==='reactor'){if(s.fault==='reactor'||s.fault==='power')s.fault=null;s.power=Math.min(s.powerCapacity,s.power+dt*.16);}else if(system==='coolant'){s.temperature=Math.max(35,s.temperature-dt*4);if(s.fault==='cooling')s.fault=null;}else if(system==='scrubber'){s.co2=Math.max(400,s.co2-dt*220);s.pressure=Math.min(101.3,s.pressure+dt*1.8);if(s.fault==='scrubber')s.fault=null;}else if(system==='stores'){if(s.food<=0||s.water<.5)return false;s.food=Math.max(0,s.food-.2*dt);s.water=Math.max(0,s.water-.1*dt);s.crewNutrition=Math.min(100,s.crewNutrition+dt*9);}else return false;return true;}
export function removePanel(s,id,role){const p=s.panels.find(p=>p.id===id);if(role!==3||!p||p.health>=60||p.removed)return false;p.removed=true;p.progress=0;return true;}
export function repairPanel(s,id,role,dt){const p=s.panels.find(p=>p.id===id);if(role!==3||!p||!p.removed||s.spares<=0)return false;p.progress=clamp(p.progress+dt/2.5,0,1);if(p.progress>=1){p.health=100;p.removed=false;s.spares--;s.hull=Math.min(100,s.hull+14);s.score+=100;}return true;}
export function useSkill(s,role,slot,teamId=0){if(s.mode!=='play'||s.ended||s.match.teams[teamId].eliminated)return false;if(slot==='f'){if(s.ultimate[role]<100)return false;s.ultimate[role]=0;}else{const field=slot==='alt'?'altCD':'abilityCD';if(s[field][role]>0)return false;s[field][role]=slot==='alt'?9:12;}if(role===0){if(slot==='q')s.boost=3;if(slot==='alt')s.decoy=5;if(slot==='f')s.shield=8;}if(role===1){if(slot==='q')s.power=Math.min(s.powerCapacity,s.power+.7);if(slot==='alt')s.temperature=Math.max(35,s.temperature-12);if(slot==='f'){s.temperature=36;s.fault=null;s.power=Math.min(s.powerCapacity,s.power+1.5);}}if(role===2){if(slot==='q')s.overdrive=7;if(slot==='alt')s.decoy=5;if(slot==='f')s.shield=5;}if(role===3){if(slot==='q')s.scanBoost=7;if(slot==='alt')s.shield=2;if(slot==='f'){s.power=Math.min(s.powerCapacity,s.power+.8);s.oxygenSuit=100;s.hull=Math.min(100,s.hull+12);}}return true;}
export const BUILD_PRIORITIES={standard:{label:'STANDARD',note:'Rack order',first:[]},structure:{label:'STRUCTURE FIRST',note:'Hull, power and life support go up first',first:['keel','reactor','battery','coolant','scrubber','cargo','stores']},systems:{label:'FLIGHT SYSTEMS FIRST',note:'Engines, bridge, turret and antenna go up first',first:['port','thruster','bridge','engine','antenna']}};
export function buildOrder(s){const first=BUILD_PRIORITIES[s.autoBuild?.priority||'standard']?.first||[];return [...s.parts].sort((x,y)=>{const a=first.indexOf(x.id),b=first.indexOf(y.id);return (a<0?99:a)-(b<0?99:b)||s.parts.indexOf(x)-s.parts.indexOf(y);});}
export function setBuildPriority(s,mode){if(!s.autoBuild?.enabled||!BUILD_PRIORITIES[mode]||s.autoBuild.t>1)return false;s.autoBuild.priority=mode;return true;}
// Plain-language status of one part for the build display.
export function machineStatus(p){return p.stage==='secured'?'SECURED':p.stage==='positioned'?'BOLTING '+Math.round(p.bolts[0]*100)+'%':p.stage==='carried'?'ARM FETCHING':'QUEUED';}
export const AUTO_BUILD_SECONDS=15;
// Assembly machines: robotic arms fetch, set and bolt every part on their own. Parts overlap in a staggered line so the
// whole ship is secured in exactly AUTO_BUILD_SECONDS of play time, whoever owns which part.
export function autoAssemble(s,dt){const a=s.autoBuild;if(!a?.enabled||s.phase!=='assembly')return false;a.t=Math.min(AUTO_BUILD_SECONDS,a.t+Math.max(0,dt));const n=s.parts.length,W=2.5,gap=n>1?(AUTO_BUILD_SECONDS-W)/(n-1):0;buildOrder(s).forEach((p,i)=>{if(p.stage==='secured')return;const k=(a.t-i*gap)/W;if(k<=0)return;if(!p.purchased){if(s.credits<p.price)return;s.credits-=p.price;p.purchased=true;}if(k<.3){p.stage='carried';return;}p.stage='positioned';const f=Math.min(1,(k-.3)/.7);p.bolts=[f,f,f];if(k>=1||a.t>=AUTO_BUILD_SECONDS){p.bolts=[1,1,1];p.stage='secured';s.score+=75;}});s.carry=s.carry.map(c=>c&&!c.startsWith('cargo:')?null:c);if(s.parts.every(p=>p.stage==='secured')){s.phase='outfit';a.enabled=false;}return true;}
// AI build recovery: after an actual teammate stalls for 10 seconds, a remote
// service arm assists that teammate through the same paid placement/fastening
// transitions. This prevents geometry/nav deadlocks while keeping the human's
// own modules exclusively interactive in Guided mode.
export function rescueStalledCrew(s,role,dt){
 if(s.phase!=='assembly'||s.autoBuild?.enabled||!s.aiAssist||role===s.selected||role<0||role>3)return false;
 const p=s.parts.find(p=>p.owner===role&&p.stage!=='secured');
 if(!p)return false;
 const row=(s.botBuildWatch??=Array.from({length:4},()=>null));
 const signature=p.stage+':'+p.bolts.map(n=>Math.floor(n*100)).join(',');
 let w=row[role];
 if(!w||w.id!==p.id){w={id:p.id,signature,age:0,rescue:false};row[role]=w;}
 if(!w.rescue){if(signature!==w.signature){w.signature=signature;w.age=0;}else w.age+=Math.max(0,Math.min(.1,dt));}
 if(!w.rescue&&w.age<10)return false;
 w.rescue=true;
 if(p.stage==='shelf')return pickPart(s,p.id,role);
 if(p.stage==='carried'){
  while(s.rotation[role]!==p.angle)rotateCarried(s,role);
  return placePart(s,role,2);
 }
 if(p.stage==='positioned'){
  const next=p.bolts.findIndex(n=>n<1);
  return next>=0&&fastenBolt(s,p.id,next,role,Math.max(0,Math.min(.1,dt))*1.5,2,true,'bot');
 }
 return false;
}
export function tickRivals(s,dt){autoAssemble(s,dt);const t=s.match.teams[0];if(!t.eliminated){if(s.phase==='assembly'){t.phase='building';t.planet='A';t.progress=s.parts.filter(p=>p.stage==='secured').length/12*.25;}else if(s.phase==='outfit'){t.phase='systems test';t.progress=.25+s.cargo.filter(c=>c.stowed).length/4*.1+Object.values(s.checks).reduce((a,b)=>a+b,0)/3*.05;}else if(s.phase==='route'){t.phase='ready';t.progress=.4;}else if(s.phase==='flight'){t.phase=s.flightLeg==='return'?'return':'outbound';t.planet='space';t.progress=(s.flightLeg==='return'?.75:.4)+Math.min(1,s.flightTime/(s.route?.duration||90))*.15;}else if(s.phase==='surface'){t.phase='surface';t.planet='B';t.progress=.6;}}tickMatch(s.match,dt);}
export function completeFlight(s){if(s.phase!=='flight'||s.flightTime<(s.flightLeg==='return'?60:(s.route?.duration||90))||s.ended)return false;if(s.flightLeg==='outbound'){s.phase='landing';s.match.teams[0].phase='surface';s.match.teams[0].planet='B';return true;}if(s.propellant<s.route.returnReserve){s.hull=0;eliminateCrew(s.match,teamId,position,planet);s.phase='spectator';}else{s.propellant-=s.route.returnReserve;arriveHome(s.match,0);s.phase='docking';}return true;}
export function setUpgrade(s,id,enabled,teamId=0){const u=UPGRADES.find(u=>u.id===id);if(!u||!['menu','select','outfit','assembly'].includes(s.mode==='play'?s.phase:s.mode))return false;const current=s.upgrades.includes(id);if(current===enabled)return true;const reserved=s.parts.filter(p=>!p.purchased).reduce((a,p)=>a+p.price,0);if(enabled&&s.credits-reserved<u.cost)return false;if(enabled){s.upgrades.push(id);s.credits-=u.cost;}else{s.upgrades=s.upgrades.filter(n=>n!==id);s.credits+=u.cost;}const sign=enabled?1:-1;s.wetMass+=u.mass*sign;s.propellant+=u.fuel*sign;s.extraLoad+=u.power*sign;s.cargoCapacity+=u.cargo*sign;s.match.teams[teamId].capacity=s.cargoCapacity;return true;}
